insert into public.dim_especies (especie_id, especie, nombre_cientifico, grupo, alias_riego, nombre_en_excel_riego, alias_nutricion, alias_bd20, tiene_ficha_bd20, origen_programa_riego, riego_mantencion_l, copa_ref_m, suelo_preferido, ph_ideal, ph_min, ph_max, rendimiento_ref_kg_pl, marco_plantacion, densidad_pl_ha, patron_parcializacion, confianza_nutricion, fuente_nutricion, nota_critica_nutricion, foliar_epoca, foliar_tejido) values
    ('duraznero', 'Duraznero', 'Prunus persica', 'Carozo', 'Duraznero', 'Duraznero', 'Duraznero', 'Duraznero', 'true', 'Base GARDENFOOD validada', '11', '2', 'Suelto, profundo, que drene bien (que el agua no se quede estancada).', '6.0 a 7.0 (ligeramente ácido a neutro)', '6', '7', '55', '4.5 × 4.5', '494', 'ESTANDAR', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 4-5; P2O5 2-3; K2O 6-8). Ca/Mg por analogía carozos.', '', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('ciruelo', 'Ciruelo', 'Prunus domestica / Prunus salicina', 'Carozo', 'Ciruelo', 'Ciruelo', 'Ciruelo', 'Ciruelo', 'true', 'Base GARDENFOOD validada', '15', '2', 'Bien drenado, tolera suelos un poco más arcillosos', '6.0 a 7.5', '6', '7.5', '60', '4.5 × 4.5', '494', 'ESTANDAR', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 4-6; P2O5 2-3; K2O 4-8). Ca/Mg por analogía carozos.', '', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('cerezo', 'Cerezo', 'Prunus avium', 'Carozo', 'Cerezo', 'Cerezo', 'Cerezo', 'Cerezo', 'true', 'Base GARDENFOOD validada', '15', '2', 'Profundo, suelto, MUY bien drenado (no tolera agua estancada)', '6.5 a 7.5', '6.5', '7.5', '35', '5.0 × 4.0', '500', 'TEMPRANA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 4-6; P2O5 2-3; K2O 8-12). Ca/Mg: Sallato y Whiting 2022 ajustado a demanda total.', 'Suspender el N desde un mes antes de cosecha: retrasa la coloración y ablanda la fruta. El N de postcosecha va APENAS TERMINA LA COSECHA, con hoja todavía activa (dic-ene), no en otoño: aplicado tarde al suelo se lava y no alcanza a construir reservas. El Ca se absorbe principalmente en primavera, desde 25 días después de plena flor.', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('damasco', 'Damasco', 'Prunus armeniaca', 'Carozo', 'Damasco', 'Damasco', 'Damasco', 'Damasco', 'true', 'Base GARDENFOOD validada', '16', '2', 'Suelto, bien drenado, profundo', '6.5 a 8.0', '6.5', '8', '40', '4.5 × 4.5', '494', 'TEMPRANA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 5-6; P2O5 2-3; K2O 6-8). Ca/Mg por analogía carozos.', '', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('nectarino', 'Nectarino', 'Prunus persica var. nucipersica', 'Carozo', 'Nectarino', 'Nectarino', 'Nectarino', 'Nectarino', 'true', 'Base GARDENFOOD validada', '15', '2', 'Suelto, profundo, drenado', '6.0 a 7.0', '6', '7', '55', '4.5 × 4.5', '494', 'ESTANDAR', 'Analogía', 'Analogía duraznero (misma especie botánica, Prunus persica). Bol. INIA 426 Cuadro 3.6.', '', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('manzano', 'Manzano', 'Malus domestica', 'Pomácea', 'Manzano', 'Manzano', 'Manzano', 'Manzano', 'true', 'Base GARDENFOOD validada', '19', '2', 'Profundo, fértil, drenado. Tolera variedad de suelos', '6.0 a 7.0', '6', '7', '100', '4.0 × 2.5', '1000', 'TARDIA', 'INIA medido', 'Bol. INIA 426 p.89: extracción medida en huerto de 60 t/ha (62 N; 28 P2O5; 130 K2O; 55 CaO; 32 MgO).', 'Vigilar la relación K:Ca. El exceso de K compite con la absorción de Ca y dispara el bitter pit. Si el huerto tiene historial de bitter pit, bajar el K y reforzar Ca foliar desde cuaja (Bol. INIA 426, p.91).', 'Enero-febrero', 'Hojas jóvenes maduras de dardos nuevos sin fruto, de la periferia. 50-100 hojas.'),
    ('peral', 'Peral', 'Pyrus communis', 'Pomácea', 'Peral', 'Peral', 'Peral', 'Peral', 'true', 'Base GARDENFOOD validada', '19', '2', 'Profundo, drenado, tolera arcilla mejor que manzano', '6.0 a 7.5', '6', '7.5', '100', '4.0 × 3.0', '833', 'TARDIA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 2.5-3; P2O5 0.6-1; K2O 3-4). Ca/Mg por analogía manzano.', '', 'Enero-febrero', 'Hojas jóvenes maduras de dardos nuevos sin fruto, de la periferia. 50-100 hojas.'),
    ('membrillo', 'Membrillo', 'Cydonia oblonga', 'Pomácea', 'Membrillo', 'Membrillo', 'Membrillo', 'Membrillo', 'true', 'Base GARDENFOOD validada', '15', '2', 'Tolera variedad, prefiere algo húmedo', '6.0 a 7.5', '6', '7.5', '50', '3.5 × 3.5', '816', 'TARDIA', 'Analogía', 'Analogía peral (misma familia, mismo hábito de fructificación). Sin dato específico chileno.', '', '', ''),
    ('limonero', 'Limonero', 'Citrus × limon', 'Cítrico', 'Limonero', 'Limonero', 'Limonero', 'Limonero', 'true', 'Base GARDENFOOD validada', '15', '2', 'Drenado, NO encharcado', '6.0 a 7.0', '6', '7', '150', '3.5 × 3.5', '816', 'PERENNE', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 Limón (N 3-3.5; P2O5 0.5-1; K2O 3-4). Ca/Mg por analogía cítricos.', '', 'Marzo-abril', 'Hojas de 4 a 7 meses de brotes de primavera sin fruto. 50-100.'),
    ('naranjo', 'Naranjo', 'Citrus × sinensis', 'Cítrico', 'Naranjo', 'Naranjo', 'Naranjo', 'Naranjo', 'true', 'Base GARDENFOOD validada', '22', '2', 'Drenado, profundo, fértil', '6.0 a 7.0', '6', '7', '120', '4.5 × 4.0', '556', 'PERENNE', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 Naranjo (N 2.5-3; P2O5 0.5-1; K2O 3-4). Ca/Mg por analogía cítricos.', '', 'Marzo-abril', 'Hojas de 4 a 7 meses de brotes de primavera sin fruto. 50-100.'),
    ('mandarino', 'Mandarino', 'Citrus reticulata', 'Cítrico', 'Mandarino', 'Mandarino', 'Mandarino', 'Mandarino', 'true', 'Base GARDENFOOD validada', '15', '2', 'Drenado, fértil', '6.0 a 7.0', '6', '7', '90', '3.5 × 3.5', '816', 'PERENNE', 'Analogía', 'Analogía naranjo (Bol. INIA 426 Cuadro 3.6). Sin dato específico para mandarino.', '', '', ''),
    ('pomelo', 'Pomelo', 'Citrus × paradisi', 'Cítrico', 'Pomelo', 'Pomelo', 'Pomelo', 'Pomelo', 'true', 'Base GARDENFOOD validada', '22', '2', 'Drenado, profundo', '6.0 a 7.0', '6', '7', '150', '4.5 × 4.0', '556', 'PERENNE', 'Analogía', 'Analogía naranjo (Bol. INIA 426 Cuadro 3.6). Sin dato específico para pomelo.', '', '', ''),
    ('nogal', 'Nogal', 'Juglans regia', 'Fruto seco', 'Nogal', 'Nogal', 'Nogal', 'Nogal', 'true', 'Base GARDENFOOD validada', '30', '2', 'Profundo (raíz pivotante), drenado, fértil', '6.5 a 7.5', '6.5', '7.5', '45', '8.0 × 8.0', '156', 'ESTANDAR', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 20-35; P2O5 15-20; K2O 30-40). Ca/Mg: S. Román, extracción neta 5 t/ha.', 'Especie de altísima extracción: entre octubre y noviembre consume el 80-85% de sus necesidades anuales (Hirzel, INIA Quilamapu). Concentrar la fertilización en esos dos meses. El error más frecuente del país es sobreaplicar N.', 'Enero-febrero', 'Hojuela terminal de la hoja compuesta del tercio medio de un brote. 50-100.'),
    ('almendro', 'Almendro', 'Prunus dulcis', 'Fruto seco', 'Almendro', 'Almendro', 'Almendro', 'Almendro', 'true', 'Base GARDENFOOD validada', '21', '2', 'Drenado, tolera secos y pedregosos', '7.0 a 8.0 (tolera algo calcáreo)', '7', '8', '15', '5.5 × 5.5', '331', 'ESTANDAR', 'Analogía', 'Analogía nogal + coeficiente de extracción de N para almendro (34 kg N/t fruto, literatura frutícola).', 'Floración muy temprana. La fertilización de otoño-invierno construye las reservas que sostienen esa floración: sin ella, la cuaja se resiente aunque no haya helada.', 'Enero-febrero', 'Hojas jóvenes maduras con pecíolo, del tercio medio de la ramilla del año. 50-100 hojas.'),
    ('higuera', 'Higuera', 'Ficus carica', 'Otros', 'Higuera', 'Higuera', 'Higuera', 'Higuera', 'true', 'Base GARDENFOOD validada', '15', '2', 'Tolera CASI TODO: arcilloso, pedregoso, pobre', '6.0 a 8.5 (tolerantísimo)', '6', '8.5', '40', '4.5 × 4.5', '494', 'ESTANDAR', 'Estimado', 'Estimado por analogía con frutales de carozo de baja exigencia. Sin dato chileno publicado.', '', '', ''),
    ('granado', 'Granado', 'Punica granatum', 'Otros', 'Granado', 'Granado', 'Granado', 'Granado', 'true', 'Base GARDENFOOD validada', '15', '2', 'Tolera variedad, prefiere drenado. Aguanta salinidad', '5.5 a 8.0 (MUY tolerante)', '5.5', '8', '30', '3.5 × 3.5', '816', 'TARDIA', 'Estimado', 'Estimado. Especie de alta demanda de K en llenado. Sin dato chileno publicado.', '', '', ''),
    ('caqui', 'Caqui', 'Diospyros kaki', 'Otros', 'Caqui', 'Caqui', 'Caqui', 'Caqui', 'true', 'Base GARDENFOOD validada', '15', '2', 'Profundo, drenado, fértil', '6.0 a 7.5', '6', '7.5', '55', '4.5 × 4.5', '494', 'TARDIA', 'Estimado', 'Estimado por analogía con pomáceas de cosecha tardía. Sin dato chileno publicado.', '', '', ''),
    ('vid', 'Vid', 'Vitis vinifera', 'Vid', 'Vid', 'Vid', 'Vid de mesa', 'Vid', 'true', 'Base GARDENFOOD validada', '11', '2.5', 'Drenado, tolera suelos pobres y pedregosos. NO le gusta rico en nitrógeno', '6.0 a 7.5', '6', '7.5', '12', '2.5 × 3.0', '1333', 'TARDIA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 Uva de mesa (N 3-3.5; P2O5 1.5-2; K2O 5-6). Ca/Mg por analogía vid.', 'Reducir o suspender el N de postcosecha para no afectar la diferenciación de yemas ni la lignificación (Bol. INIA 426, p.89-90).', 'Noviembre, fin de floración', 'Pecíolos opuestos al racimo, zona exterior de la planta. 50-100.'),
    ('arandano', 'Arándano', 'Vaccinium corymbosum', 'Baya', 'Arandano', 'Arandano', 'Arándano', 'Arandano', 'true', 'Base GARDENFOOD validada', '4', '1.5', 'ÁCIDO (pH 4.5-5.5), suelto, con materia orgánica. Es EXIGENTE en suelo', '4.5 a 5.5 (ÁCIDO — esto es CRÍTICO)', '4.5', '5.5', '5', '1.2 × 3.0', '2778', 'ESTANDAR', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 3-6; P2O5 1-2; K2O 5-8). Ca/Mg: Vidal 2007, U. de Concepción.', 'pH 4.5-5.5 OBLIGATORIO. Usar SOLO fuentes acidificantes: sulfato de amonio, sulfato de potasio, sulfato de magnesio, yeso. PROHIBIDO: cal, cal dolomítica, ceniza, guano de gallina, nitrato de calcio y salitre (suben el pH y provocan clorosis férrica). El Bol. INIA 426 Cuadro 3.5 lo señala como la única excepción de pH del catálogo, junto al lupino.', 'Enero-febrero, una semana después de terminada la cosecha', 'Hojas recientemente maduras del brote anual fructífero. 50-100.'),
    ('olivo', 'Olivo', 'Olea europaea', 'Oleáceo', 'Olivo', 'Olivo', 'Olivo', 'Olivo', 'true', 'Base GARDENFOOD validada', '15', '3', 'Tolera suelos pobres, pedregosos, calcáreos. Drenaje es OBLIGATORIO', '6.5 a 8.5 (tolerantísimo)', '6.5', '8.5', '35', '5.0 × 5.0', '400', 'PERENNE', 'INIA medido', 'Hirzel, Barrera y Ried 2013, Tierra Adentro 102 (INIA). Arbequina 11 años: N 7.1; P2O5 1.9; K2O 9.2.', 'El exceso de N baja la calidad del aceite. El K sube la calidad del aceite, la tasa de fotosíntesis y la productividad (Hirzel et al. 2013, INIA).', '', ''),
    ('frutilla', 'Frutilla', 'Fragaria × ananassa', 'Berries', 'Frutilla', 'Frutilla', 'Frutilla', '', 'false', 'PROPUESTA — pendiente de validar', '2', '0.3', 'Suelto, arenoso-franco, MUY bien drenado y rico en materia orgánica. La raíz es superficial (20-30 cm): se seca rápido.', '5.5 a 6.5', '5.5', '6.5', '0.45', '0.28 × 0.9', '39683', 'TEMPRANA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 2-3; P2O5 1-2; K2O 3-5). Ca/Mg por analogía berries.', '', 'Primavera, primer ciclo con frutos presentes', 'Hojas sin pecíolo recientemente maduras, de todas las zonas de la planta. 50-100.'),
    ('frambuesa', 'Frambuesa', 'Rubus idaeus', 'Berries', 'Frambuesa', 'Frambuesa', 'Frambuesa', '', 'false', 'PROPUESTA — pendiente de validar', '6', '1', 'Franco arenoso, profundo y bien drenado. No tolera el agua estancada ni un minuto.', '5.5 a 6.5', '5.5', '6.5', '1.8', '0.5 × 2.5', '8000', 'ESTANDAR', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 Frambueso (N 8-10; P2O5 3-4; K2O 5-8). Ca/Mg por analogía berries de caña.', 'Fructifica en madera del mismo año o del año anterior según el tipo (remontante o no). Alta relación de extracción entre biomasa total y fruta: la dosis parece alta para el rendimiento, y está correcta.', 'Segunda quincena de diciembre a enero', 'Hojas recientemente maduras de las cañas laterales del año. 50-100.'),
    ('mora', 'Mora', 'Rubus fruticosus', 'Berries', 'Mora', 'Mora', 'Mora (sin espina)', '', 'false', 'PROPUESTA — pendiente de validar', '8', '1.5', 'Se adapta a casi cualquier suelo con tal de que drene. Es el berry más rústico.', '5.5 a 7.0', '5.5', '7', '5', '1.2 × 3.0', '2778', 'ESTANDAR', 'Analogía', 'Analogía frambueso (Bol. INIA 426 Cuadro 3.6), mismo género Rubus y hábito de caña bienal.', '', '', ''),
    ('kiwi', 'Kiwi', 'Actinidia deliciosa', 'Enredadera frutal', 'Kiwi', 'Kiwi', 'Kiwi', '', 'false', 'PROPUESTA — pendiente de validar', '30', '3.5', 'Franco arenoso profundo, con drenaje perfecto. Raíz superficial y muy sensible a la asfixia: 48 horas con agua estancada la matan.', '5.5 a 6.5 (no tolera suelos calcáreos)', '5.5', '6.5', '60', '4.5 × 4.5', '494', 'TARDIA', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 2-3; P2O5 1-1.5; K2O 6-8). Ca/Mg: Hirzel 2014, acumulación en frutos de kiwi.', 'Sus necesidades de K duplican a las de N (Bol. INIA 426, p.86). No aplicar N en postcosecha: la cosecha es tardía y el N tardío impide la lignificación de la madera.', 'Noviembre, enero y febrero', 'Hojas jóvenes maduras antes de la formación de frutos. 60-100.'),
    ('avellano', 'Avellano', 'Corylus avellana', 'Frutos secos', 'Avellano Europeo', 'Avellano', 'Avellano Europeo', '', 'false', 'PROPUESTA — pendiente de validar', '15', '3.5', 'Franco, profundo y bien drenado. Tolera bien el frío y la lluvia de invierno del sur.', '6.0 a 7.5', '6', '7.5', '5', '5.5 × 5.0', '364', 'ESTANDAR', 'Analogía', 'Analogía fruto seco + Redagrícola: hojas son el gran consumidor (75 kg N y 92 kg K2O/ha a IAF 5).', '', '', ''),
    ('nispero', 'Níspero', 'Eriobotrya japonica', 'Siempreverde', 'Níspero Japonés', 'Níspero', 'Níspero Japonés', '', 'false', 'PROPUESTA — pendiente de validar', '19', '3.5', 'Se adapta bien, con tal de que drene. Tolera la costa y el viento salino.', '6.0 a 7.5', '6', '7.5', '45', '4.5 × 4.5', '494', 'PERENNE', 'Estimado', 'Estimado. Perennifolio de cosecha invierno-primavera. Sin dato chileno publicado.', '', '', ''),
    ('lucuma', 'Lúcuma', 'Pouteria lucuma', 'Siempreverde subtropical', 'Lúcuma', 'Lúcuma', 'Lúcuma', '', 'false', 'PROPUESTA — pendiente de validar', '22', '4', 'Suelto y MUY bien drenado. Es más sensible al exceso de agua que a la falta.', '6.0 a 7.0', '6', '7', '90', '7.0 × 7.0', '204', 'PERENNE', 'Estimado', 'Estimado por analogía con subtropicales de hoja persistente. Sin dato chileno publicado.', '', '', ''),
    ('palto', 'Palto', 'Persea americana', 'Siempreverde subtropical', 'Palto', 'Palta', 'Palto', '', 'false', 'PROPUESTA — pendiente de validar', '26', '4', 'Suelto, profundo y con drenaje EXCELENTE. Raíz superficial y muy sensible a la asfixia y a Phytophthora. En suelo pesado, plante sobre camellón.', '5.5 a 7.0', '5.5', '7', '70', '7.0 × 7.0', '204', 'PERENNE', 'INIA rango', 'Bol. INIA 426 Cuadro 3.6 (N 8-12; P2O5 5-6; K2O 10-15). Ca/Mg por analogía palto.', 'Muy sensible a suelos calcáreos y a la asfixia radicular. Priorizar el drenaje antes que la dosis. Sensible al cloruro: no usar muriato de potasio.', 'Marzo-abril', 'Hojas de 5 a 7 meses de brotes de primavera sin fruto. 100 hojas.'),
    ('chirimoya', 'Chirimoya', 'Annona cherimola', 'Subtropical', 'Chirimoya', 'Chirimoya', 'Chirimoya', '', 'false', 'PROPUESTA — pendiente de validar', '15', '4', 'Franco, profundo y bien drenado. No tolera heladas ni suelo pesado.', '6.5 a 7.5', '6.5', '7.5', '60', '5.5 × 5.5', '331', 'PERENNE', 'Estimado', 'Estimado por analogía con subtropicales de hoja persistente. Sin dato chileno publicado.', '', '', ''),
    ('papayo_chileno', 'Papayo chileno', 'Vasconcellea pubescens', 'Nativo subtropical', 'Papayo Chileno', 'Papayo chileno', 'Papayo Chileno', '', 'false', 'PROPUESTA — pendiente de validar', '11', '2.5', 'Suelto y muy bien drenado. El cuello del tallo se pudre si le queda agua encima.', '6.0 a 7.0', '6', '7', '30', '2.5 × 2.5', '1600', 'PERENNE', 'Estimado', 'Estimado. Producción continua todo el año. Sin dato chileno publicado.', '', '', '');
