insert into public.dim_macrozonas (macrozona_id, macrozona, factor_n, factor_p2o5, factor_k2o, factor_cao, factor_mgo, parcialidades_min_ano, por_que) values
    ('NOR', 'Norte (Atacama-Coquimbo)', '1', '1.3', '1', '0.5', '0.8', '10', 'Suelos alcalinos y calcáreos: el P se fija como fosfato de calcio y hay que subir la dosis o aplicarlo localizado. El Ca sobra en el suelo, se reduce a la mitad. Sin lluvia no hay lavado de N, pero la alta evapotranspiración obliga a fraccionar mucho. Vigilar salinidad: preferir fuentes de bajo índice salino.'),
    ('VAL', 'Valparaíso-Aconcagua', '1', '1.1', '1', '0.7', '0.9', '8', 'Zona de referencia mediterránea. Ajuste leve de P por suelos algo calcáreos en el interior y menor necesidad de Ca.'),
    ('RM', 'Santiago-RM', '1', '1', '1', '0.7', '0.9', '8', 'Zona de referencia: los factores del Cuadro 3.6 se aplican sin corrección. Suelos con Ca generalmente adecuado.'),
    ('CSU', 'Centro-Sur (O''Higgins-Maule)', '1.05', '1.05', '1', '1', '1', '8', 'Precipitación de 600-900 mm concentrada en invierno: leve lavado de N si se aplica temprano. Suelos variados, en general de fertilidad adecuada.'),
    ('TRA', 'Transición (Ñuble-Biobío)', '1.15', '1.2', '1.1', '1.2', '1.2', '10', 'Suelos trumaos (Andisoles) de origen volcánico con alta retención de fósforo y acidez moderada. Precipitación de 1.000-1.300 mm: lavado real de N, K y Mg. Subir Ca y Mg porque el complejo de intercambio está desbalanceado.'),
    ('SUR', 'Sur (Araucanía-Los Lagos)', '1.25', '1.4', '1.2', '1.4', '1.3', '12', 'Andisoles con la mayor capacidad de fijación de P del país y saturación de aluminio en sectores. Precipitación sobre 1.300 mm: pérdida importante de nutrientes móviles. Aquí el encalado previo suele rendir más que subir la dosis, salvo en arándano donde nunca se encala.');
insert into public.dim_suelos (suelo_id, suelo, nombres_usda, agua_min_mm_m, agua_max_mm_m, factor_suelo, como_se_siente, como_manejarlo) values
    ('G', 'Gruesa (arenosa)', 'Arena, arena francosa, arena fina', '50', '100', '0.7', 'Arenoso al tacto, no forma cinta, se desarma solo.', 'Suelo que se seca rápido: riegue MÁS SEGUIDO y con MENOS agua cada vez. Un riego grande se le escapa hacia abajo y se pierde. Ponga mulch (paja, pasto seco, hojas) de 10 cm bajo la copa y agregue compost cada año: es lo que más le sube la retención de agua.'),
    ('MG', 'Moderadamente gruesa', 'Franco arenoso, franco arenoso fino', '108', '142', '0.85', 'Forma bola pero cinta corta (menos de 2,5 cm). Áspero al frotar mojado.', 'Suelo cómodo pero algo suelto. Riegue en dos tiempos (mitad del agua, esperar 20 minutos, la otra mitad) para que no escurra. Mulch de 8-10 cm y compost anual.'),
    ('M', 'Media (franca)', 'Franco, franco limoso, franco arenoso arcilloso', '125', '175', '1', 'Forma cinta de 2,5 a 5 cm. Ni muy áspero ni muy jabonoso.', 'El mejor suelo para frutales: retiene bien y drena bien. Mantenga el mulch y no lo pise cuando está mojado, porque se compacta. Riegue en el borde de la copa, no pegado al tronco.'),
    ('F', 'Fina (arcillosa)', 'Arcilla, franco arcilloso, franco arcilloso limoso', '133', '200', '1.15', 'Forma cinta larga (más de 5 cm), se pega y es plástico.', 'Suelo que retiene mucha agua: riegue MENOS SEGUIDO y con MÁS agua cada vez, pero LENTO. Si el agua se empoza, pare y espere. El riesgo real acá no es la sequía, es la asfixia de raíces: nunca riegue si al apretar el suelo queda pegajoso y resbaloso.');
insert into public.dim_humedad (humedad_n, nivel, pct_min, pct_max, factor_riego, factor_control, que_significa, se_ve_gruesa, se_ve_mod_gruesa, se_ve_media, se_ve_fina) values
    ('1', '0-25 % — muy seco', '0', '25', '1.3', '0', 'RIEGUE HOY. El suelo está en déficit fuerte: el árbol ya está sufriendo.', 'Se ve seco y suelto. Se mantiene junto si no lo mueve, pero al apretar quedan granos de arena sueltos en los dedos. No forma bola.', 'Seco. Forma una bola muy débil que se desarma sola; los granos se caen fácilmente de la bola.', 'Seco. Los terrones se desmoronan al apretar, los agregados se caen solos, no deja humedad en los dedos.', 'Seco. Los agregados se separan con facilidad, los terrones cuesta desmoronarlos al apretar.'),
    ('2', '25-50 % — seco (punto de riego)', '25', '50', '1', '0', 'RIEGUE HOY. Este es el momento correcto para regar frutales.', 'Levemente húmedo. Forma una bola muy débil con las marcas de los dedos marcadas. Quedan granos de arena sueltos en la palma.', 'Levemente húmedo. Bola débil con marcas de dedos definidas, color oscuro, no mancha de agua en los dedos, se caen granos.', 'Ligeramente húmedo. Bola débil de superficie rugosa, no deja manchas de agua en los dedos, se caen pocos granos.', 'Ligeramente húmedo. Bola débil, muy pocos agregados se caen, sin manchas de agua, los terrones se aplanan al apretar.'),
    ('3', '50-75 % — húmedo', '50', '75', '0', '0.35', 'NO RIEGUE todavía. Queda agua disponible en la zona de raíces.', 'Húmedo. Forma una bola débil, color oscuro, mancha moderada de agua en los dedos. NO forma cinta.', 'Húmedo. Bola con marcas de dedos definidas, manchas leves de suelo/agua en los dedos, color oscuro, no se pega.', 'Húmedo. Forma bola, manchas muy leves en los dedos, color oscuro, maleable, forma una cinta DÉBIL entre pulgar e índice.', 'Húmedo. Bola blanda con marcas de dedos definidas, manchas suaves en los dedos, forma CINTA entre pulgar e índice.'),
    ('4', '75-100 % — muy húmedo', '75', '100', '0', '0.6', 'NO RIEGUE. El suelo está casi lleno de agua.', 'Mojado. Forma bola débil, color oscuro, manchas gruesas de agua en los dedos, quedan granos sueltos. NO forma cinta.', 'Mojado. La bola deja marca húmeda en la mano, manchas medias en los dedos, forma una cinta DÉBIL entre pulgar e índice.', 'Mojado. Bola con marcas de dedos bien definidas, capa liviana a gruesa de suelo/agua en los dedos, forma CINTA.', 'Mojado. Bola que deja capa despareja de media a gruesa en los dedos, forma CINTA con facilidad.'),
    ('5', '100 % — capacidad de campo', '100', '100', '0', '0.75', 'NO RIEGUE. El suelo está lleno. Si sigue así 3 días, revise el drenaje.', 'Mojado. Forma bola débil y deja una marca mojada en la palma al abrirla.', 'Mojado. Bola blanda; al apretar o sacudir aparece agua en la superficie; deja capa media a gruesa en los dedos.', 'Mojado. Bola blanda; aparece agua en la superficie al apretar o sacudir; deja capa media a gruesa en los dedos.', 'Mojado. Bola blanda; aparece agua al apretar o sacudir; deja capa pegajosa, resbalosa en los dedos.');
insert into public.dim_edad (edad_n, edad, anos_min, anos_max, factor_litros, factor_dias) values
    ('1', 'Recién plantado (0-1 año)', '0', '1', '0.3', '0.55'),
