insert into public.dim_parcializacion (clave, patron, nutriente, brotacion_a_cuaja, cuaja_a_cosecha, postcosecha, rango_inia, dentro_rango, que_significa) values
    ('ESTANDAR|N', 'ESTANDAR', 'N', '0.2', '0.5', '0.3', '10-30 / 40-60 / 20-40', 'SÍ', 'Cosecha a mediados de temporada estival. Aplicación directa del Cuadro 3.7 INIA.'),
    ('ESTANDAR|P2O5', 'ESTANDAR', 'P₂O₅', '0.3', '0.4', '0.3', '20-30 / 30-40 / 20-30', 'SÍ', ''),
    ('ESTANDAR|K2O', 'ESTANDAR', 'K₂O', '0.15', '0.55', '0.3', '10-20 / 50-60 / 20-30', 'SÍ', ''),
    ('ESTANDAR|CaO', 'ESTANDAR', 'CaO', '0.3', '0.7', '0', '20-40 / 60-80 / —', 'SÍ', ''),
    ('ESTANDAR|MgO', 'ESTANDAR', 'MgO', '0', '0.55', '0.45', '— / 50-60 / 40-50', 'SÍ', ''),
    ('TEMPRANA|N', 'TEMPRANA', 'N', '0.2', '0.45', '0.35', '10-30 / 40-60 / 20-40', 'SÍ', 'Cosecha temprana (nov-dic). Se aumenta la fracción de postcosecha: la planta tiene un período vegetativo largo después de cosechar y ahí forma las yemas del año siguiente.'),
    ('TEMPRANA|P2O5', 'TEMPRANA', 'P₂O₅', '0.3', '0.4', '0.3', '20-30 / 30-40 / 20-30', 'SÍ', ''),
    ('TEMPRANA|K2O', 'TEMPRANA', 'K₂O', '0.15', '0.55', '0.3', '10-20 / 50-60 / 20-30', 'SÍ', ''),
    ('TEMPRANA|CaO', 'TEMPRANA', 'CaO', '0.3', '0.7', '0', '20-40 / 60-80 / —', 'SÍ', ''),
    ('TEMPRANA|MgO', 'TEMPRANA', 'MgO', '0', '0.5', '0.5', '— / 50-60 / 40-50', 'SÍ', ''),
    ('TARDIA|N', 'TARDIA', 'N', '0.3', '0.65', '0.05', '10-30 / 40-60 / 20-40', 'AJUSTADO', 'Cosecha tardía (mar-jun). Se reduce la postcosecha y el N se suspende casi por completo, para no retrasar la lignificación de la madera antes del invierno.
insert into public.cat_fert_casero (producto, etiqueta, n_pct, p_pct, k_pct, calcio_pct, magnesio_pct, g_por_cucharada, se_reparte, como_pedirlo_y_cuidar) values
    ('Urea', '46-0-0', '46', '', '', '', '', '11', 'Sí, cada vez', 'Se vende en cualquier agrícola, en sacos de 1, 5 o 25 kg. Riega inmediatamente después de aplicarla. Si queda seca en la superficie, se evapora y pierdes la mitad.'),
    ('Sulfato de amonio', '21-0-0 con azufre', '21', '', '', '', '', '14', 'Sí, cada vez', 'Pídelo por su nombre. Es el nitrogenado de los arándanos. Acidifica el suelo, que es justo lo que el arándano necesita. En otras especies úsalo con moderación.'),
    ('Nitrato de calcio', '15,5-0-0 con 26,5% de calcio', '15.5', '', '', '26.5', '', '14', 'Sí, cada vez', 'Se vende granulado o soluble. Cualquiera sirve. Guárdalo bien cerrado: absorbe humedad del aire y se apelmaza.'),
    ('Superfosfato triple', '0-46-0', '', '46', '', '14', '', '15', 'Una vez al año', 'En la agrícola pídelo como SFT o superfosfato triple. Entiérralo unos centímetros. El fósforo no se mueve en el suelo: si lo dejas arriba, la raíz nunca lo alcanza.'),
    ('Sulfato de potasio', '0-0-50 con azufre', '', '', '50', '', '', '16', 'Sí, cada vez', 'También lo verás como SOP o sulfato de potasa. Más caro que el muriato, pero no aporta cloro y da mejor sabor a la fruta.'),
    ('Sulpomag', '0-0-22 con 18% de magnesio', '', '', '22', '', '18', '15', 'Sí, cada vez', 'También se vende como sulfato doble de potasio y magnesio, o K-Mag. Resuelve potasio y magnesio en un solo producto, sin tocar el pH.'),
    ('Sulfato de magnesio', '25% de magnesio', '', '', '', '', '25', '13', 'Sí, cada vez', 'En farmacia se llama sal de Epsom; en agrícola, kieserita o sulfato de magnesio. Apto para arándano: aporta magnesio sin subir el pH.'),
    ('Yeso agrícola', '32% de calcio con azufre', '', '', '', '32', '', '13', 'Una vez al año', 'Pide yeso agrícola, no yeso de construcción. Aporta calcio sin subir el pH. Es la única forma de darle calcio a un arándano.'),
    ('Nitrato de potasio', '13-0-46', '13', '', '46', '', '', '14', 'Sí, cada vez', 'También se vende como salitre potásico soluble. Revisa la etiqueta: existe una versión 15-0-14 más débil. Se disuelve muy bien. Aporta potasio y algo de nitrógeno a la vez.'),
    ('Fosfato monoamónico soluble', '12-61-0', '12', '61', '', '', '', '14', 'Sí, cada vez', 'Pídelo como MAP soluble. Acidifica el agua de riego, lo que ayuda a mantener limpios los goteros.'),
    ('Sal de Epsom', '16% de magnesio', '', '', '', '', '16', '12', 'Sí, cada vez', 'En farmacia como sal de Epsom, o en agrícola como sulfato de magnesio heptahidratado. Nunca la mezcles en el mismo balde con nitrato de calcio: se forma una sal blanca que tapa los goteros.');
insert into public.cat_fert_tecnico (producto_id, tipo, fertilizante, n_pct, p2o5_pct, k2o_pct, cao_pct, mgo_pct, s_pct, reaccion_ph, apto_organico, solubilidad_g_l, para_que_y_cuidados) values
    ('urea_granulado', 'Granulado', 'Urea', '46', '', '', '', '', '', 'Acidificante', 'No', '', 'La fuente de N más concentrada y barata. Se volatiliza si queda en superficie sin incorporar ni regar.'),
    ('sulfato_de_amonio_granulado', 'Granulado', 'Sulfato de amonio', '21', '', '', '', '', '24', 'Muy acidificante', 'No', '', 'N amoniacal + azufre. Es EL nitrogenado del arándano: baja el pH en vez de subirlo.'),
    ('salitre_sodico_nitrato_de_sodio_granulado', 'Granulado', 'Salitre sódico (nitrato de sodio)', '16', '', '', '', '', '', 'Alcalinizante', 'Restringido', '', 'N nítrico de acción inmediata. Aporta sodio: evitar en suelos salinos o de riego con agua dura.'),
    ('salitre_potasico_nitrato_de_potasio_granulado_granulado', 'Granulado', 'Salitre potásico (nitrato de potasio granulado)', '15', '', '14', '', '', '', 'Neutra', 'No', '', 'Aporta N y K juntos. Muy usado en llenado de fruta. Verificar la riqueza del envase: existen formulaciones 15-0-14 y 13-0-46.'),
    ('nitrato_de_calcio_granulado_granulado', 'Granulado', 'Nitrato de calcio granulado', '15.5', '', '', '26.5', '', '', 'Alcalinizante', 'No', '', 'Única fuente que aporta N y Ca simultáneamente. Higroscópico: guardar sellado.'),
    ('superfosfato_triple_sft_granulado', 'Granulado', 'Superfosfato triple (SFT)', '', '46', '', '14', '', '', 'Neutra', 'No', '', 'Fuente concentrada de P. Aplicar localizado en la zona de raíces: el P no se mueve en el suelo.'),
    ('superfosfato_normal_granulado', 'Granulado', 'Superfosfato normal', '', '21', '', '28', '', '12', 'Neutra', 'No', '', 'Menos concentrado que el SFT pero aporta Ca y S. Buena opción de fondo a la plantación.'),
    ('fosfato_diamonico_dap_granulado', 'Granulado', 'Fosfato diamónico (DAP)', '18', '46', '', '', '', '', 'Acidificante', 'No', '', 'N + P en un solo producto. No mezclar con cal ni con productos alcalinos: se pierde el N por volatilización.'),
    ('fosfato_monoamonico_map_granulado', 'Granulado', 'Fosfato monoamónico (MAP)', '12', '52', '', '', '', '', 'Acidificante', 'No', '', 'Similar al DAP pero más ácido en la zona de aplicación. Mejor que el DAP en suelos alcalinos del norte.'),
    ('muriato_de_potasio_kcl_granulado', 'Granulado', 'Muriato de potasio (KCl)', '', '', '60', '', '', '', 'Neutra', 'No', '', 'El potásico más barato. Aporta cloruro: evitar en suelos salinos y en especies sensibles al cloro.'),
    ('sulfato_de_potasio_sop_granulado', 'Granulado', 'Sulfato de potasio (SOP)', '', '', '50', '', '', '18', 'Neutra', 'Sí', '', 'K sin cloro + azufre. Más caro que el KCl pero obligatorio en suelos salinos y preferido en fruta de exportación.'),
    ('sulpomag_sulfato_doble_k_mg_granulado', 'Granulado', 'Sulpomag (sulfato doble K-Mg)', '', '', '22', '', '18', '22', 'Neutra', 'Sí', '', 'Aporta K, Mg y S a la vez. La forma más práctica de corregir Mg sin subir el pH.'),
    ('sulfato_de_magnesio_kieserita_granulado', 'Granulado', 'Sulfato de magnesio (kieserita)', '', '', '', '', '25', '20', 'Neutra', 'Sí', '', 'Corrección de Mg sin aportar Ca ni subir pH. Apto para arándano.'),
    ('yeso_agricola_sulfato_de_calcio_granulado', 'Granulado', 'Yeso agrícola (sulfato de calcio)', '', '', '', '32', '', '18', 'Neutra', 'Sí', '', 'Aporta Ca y S SIN subir el pH. Es la fuente de Ca correcta en suelos ácidos y la única aceptable cerca de arándano.'),
    ('cal_dolomitica_granulado', 'Granulado', 'Cal dolomítica', '', '', '', '30', '20', '', 'Muy alcalinizante', 'Sí', '', 'Enmienda para subir pH y aportar Ca y Mg en suelos ácidos del sur. NUNCA en arándano: lo mata.'),
    ('roca_fosforica_granulado', 'Granulado', 'Roca fosfórica', '', '29', '', '35', '', '', 'Neutra', 'Sí', '', 'P de liberación lenta, solo eficaz en suelos ácidos (pH bajo 6). Fuente de P autorizada en orgánico.'),
    ('guano_rojo_fosfato_natural_granulado', 'Granulado', 'Guano rojo (fosfato natural)', '1', '10', '1', '25', '0.5', '', 'Neutra', 'Sí', '', 'Fosforita chilena. Liberación lenta, aporta también Ca y micros. Verificar la riqueza del lote.'),
    ('compost_maduro_referencial_granulado', 'Granulado', 'Compost maduro (referencial)', '1.2', '0.6', '1', '2', '0.4', '0.2', 'Variable', 'Sí', '', 'Riqueza referencial de compost de guano vacuno maduro. SIEMPRE pedir análisis del lote: varía mucho.'),
    ('nitrato_de_potasio_soluble_ultrasol_potassium_similar_soluble', 'Soluble', 'Nitrato de potasio soluble (Ultrasol Potassium / similar)', '13', '', '46', '', '', '', '', '', '316', 'El caballo de batalla del fertirriego en llenado de fruta. Solubilidad alta y sin residuo.'),
    ('nitrato_de_calcio_soluble_ultrasol_calcium_similar_soluble', 'Soluble', 'Nitrato de calcio soluble (Ultrasol Calcium / similar)', '15.5', '', '', '26.5', '', '', '', '', '1200', 'N + Ca. NUNCA mezclar en el mismo estanque con sulfatos ni fosfatos: precipita yeso y tapa los goteros.'),
    ('nitrato_de_magnesio_soluble_ultrasol_magnit_similar_soluble', 'Soluble', 'Nitrato de magnesio soluble (Ultrasol Magnit / similar)', '11.5', '', '', '', '15', '', '', '', '700', 'Corrección rápida de Mg vía riego, sin aportar sulfato.'),
    ('fosfato_monoamonico_soluble_map_soluble_soluble', 'Soluble', 'Fosfato monoamónico soluble (MAP soluble)', '12', '61', '', '', '', '', '', '', '370', 'Fuente soluble de P. Acidifica la solución, lo que ayuda a mantener limpia la red de goteo.'),
    ('acido_fosforico_85_soluble', 'Soluble', 'Ácido fosfórico 85%', '', '61', '', '', '', '', '', '', 'Muy alta', 'P + limpieza de la línea de riego. PELIGROSO: siempre ácido sobre agua, nunca al revés. Usar EPP.'),
    ('sulfato_de_potasio_soluble_soluble', 'Soluble', 'Sulfato de potasio soluble', '', '', '50', '', '', '18', '', '', '110', 'K sin cloro. Solubilidad limitada: disolver con agitación y agua templada.'),
    ('sulfato_de_magnesio_heptahidratado_sal_de_epsom_soluble', 'Soluble', 'Sulfato de magnesio heptahidratado (sal de Epsom)', '', '', '', '', '16', '13', '', '', '710', 'Mg + S soluble y barato. Apto para arándano. No mezclar con nitrato de calcio.'),
    ('urea_soluble', 'Soluble', 'Urea', '46', '', '', '', '', '', '', '', '1080', 'N más concentrado y económico para fertirriego. No acidifica la línea.'),
    ('sulfato_de_amonio_soluble_soluble', 'Soluble', 'Sulfato de amonio soluble', '21', '', '', '', '', '24', '', '', '750', 'N amoniacal acidificante. Fuente preferente en arándano vía fertirriego.'),
    ('nitrato_de_amonio_soluble', 'Soluble', 'Nitrato de amonio', '34', '', '', '', '', '', '', '', 'Muy alta', '50% nítrico y 50% amoniacal. Compra regulada en Chile: requiere autorización.'),
    ('ultrasol_multiproposito_npk_soluble_mg_y_micros_soluble', 'Soluble', 'Ultrasol Multipropósito (NPK soluble + Mg y micros)', '18', '18', '18', '', '2', '', '', '', '400', 'Formulación equilibrada para huertos pequeños y macetas: resuelve N-P-K en un solo producto.');
insert into public.fact_riego_mes (clave, especie_id, especie_alias, mes, mes_n, etapa, dias_min, dias_max, litros_min, litros_max, reposo, que_vera, consejo, frecuencia_original, volumen_original) values
    ('duraznero|1', 'duraznero', 'Duraznero', 'Enero', '1', 'Maduración', '3', '4', '60', '80', 'false', 'Frutos cambiando de color', '10 días antes de cosechar reducir riego para concentrar sabor', 'Cada 3-4 días', '60-80 litros por árbol'),
